//--------------------------------------------------------------------------//

typedef enum
{
    DEI_RF_ID0 , 
    DEI_RF_ID1 , 
    DEI_RF_ID2 , 
    DEI_RF_ID3 ,

    DEI_RF_ID_COUNT

}Dei_Rf_Id ; 

//--------------------------------------------------------------------------//

typedef enum
{
    DEI_RF_CLEAN_ANTENNA  = 0 , 
    DEI_RF_NOISY_ANTENNA  = 1

}Dei_Rf_Antenna_Type ; 

//--------------------------------------------------------------------------//

typedef union s_Dei_Rf_Frame
{
    struct
    {
        unsigned encrypt    :32;    
        unsigned sn0        :8;               
        unsigned pl0        :8;                
        unsigned batt_low   :1;
        unsigned press_type :1;

    }normal ; 

    struct
    {
        unsigned sn         :32;
        unsigned sync_count :16;
        unsigned pl         :8 ;

    }programming ;                     

}Dei_Rf_Frame ; 


//--------------------------------------------------------------------------//

typedef enum
{
    DEI_RF_MODE_NORMAL_RX      , 
    DEI_RF_MODE_PROGRAMMING_RX ,
    DEI_RF_MODE_NORMAL_TX      ,
    DEI_RF_MODE_PROGRAMMING_TX ,
    DEI_RF_MODE_PAGGING_TX     ,
    DEI_RF_MODE_PAGGING_STOP  

}Dei_Rf_Mode ; 

//--------------------------------------------------------------------------//
                        

